<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { api, get } from "../../api/http";
import { useRoute, useRouter } from "vue-router";
const route = useRoute(); const router = useRouter(); const id = route.params.id as string | undefined; const tags = ref<any[]>([]); const categories = ref<any[]>([]); const saving = ref(false); const error = ref("");
const article = ref<any>({ title: "", slug: "", summary: "", content: "# 新文章", coverUrl: "", status: "DRAFT", categoryId: null, tagIds: [] });
const title = computed(() => id ? "编辑文章" : "新建文章");
async function load() { try { const [tagList, categoryList] = await Promise.all([get<any[]>("/tags"), get<any[]>("/categories")]); tags.value = tagList; categories.value = categoryList; if (id) article.value = await get(`/admin/articles/${id}`); } catch { router.push("/admin/login"); } }
async function save() { saving.value = true; error.value = ""; try { if (id) await api.put(`/admin/articles/${id}`, article.value); else await api.post("/admin/articles", article.value); router.push("/admin/articles"); } catch { error.value = "保存失败：请检查必填字段和 slug 是否重复。"; } finally { saving.value = false; } }
async function publish() { if (!id) return; saving.value = true; try { await api.post(`/admin/articles/${id}/publish`); router.push("/admin/articles"); } finally { saving.value = false; } }
onMounted(load);
</script>
<template><section><div class="page-heading"><div><div class="breadcrumb"><RouterLink to="/admin/articles">文章管理</RouterLink><span>/</span><span>{{ title }}</span></div><h1>{{ title }}</h1><p>{{ id ? "更新内容、状态和文章元数据。" : "创建一篇新的 Markdown 文章。" }}</p></div><div class="editor-actions"><RouterLink class="button" to="/admin/articles">取消</RouterLink><button v-if="id" class="button" type="button" :disabled="saving" @click="publish">发布</button><button class="button button--primary" :disabled="saving" @click="save">{{ saving ? "保存中…" : "保存文章" }}</button></div></div><form class="editor-grid" @submit.prevent="save"><div class="card"><div class="card__header"><h2 class="card__title">文章内容</h2><span class="table-subtitle">Markdown</span></div><div class="card__body editor-fields"><div class="field"><label>标题</label><input v-model="article.title" class="input input--title" placeholder="给文章一个清晰的标题" required /></div><div class="field"><label>摘要</label><textarea v-model="article.summary" class="textarea" placeholder="用于文章列表的简短介绍"></textarea></div><div class="field"><label>正文</label><textarea v-model="article.content" class="textarea markdown-editor" placeholder="使用 Markdown 编写正文" required></textarea></div></div></div><aside class="editor-sidebar"><div class="card"><div class="card__header"><h2 class="card__title">发布设置</h2></div><div class="card__body editor-fields"><div class="field"><label>状态</label><select v-model="article.status" class="select"><option value="DRAFT">草稿</option><option value="PUBLISHED">已发布</option><option value="ARCHIVED">已归档</option></select></div><div class="field"><label>分类</label><select v-model="article.categoryId" class="select"><option :value="null">未分类</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.name }}</option></select></div><div class="field"><label>标签</label><select v-model="article.tagIds" class="select tag-select" multiple><option v-for="tag in tags" :key="tag.id" :value="tag.id">{{ tag.name }}</option></select><span class="field-hint">按住 Ctrl / ⌘ 选择多个标签</span></div></div></div><div class="card"><div class="card__header"><h2 class="card__title">SEO 与封面</h2></div><div class="card__body editor-fields"><div class="field"><label>Slug</label><input v-model="article.slug" class="input" placeholder="my-article-slug" required /></div><div class="field"><label>封面 URL</label><input v-model="article.coverUrl" class="input" placeholder="https://..." /></div></div></div></aside></form><p v-if="error" class="form-error">{{ error }}</p></section></template>

